t.script:
(() => {
    const {token, mode} = document.currentScript.dataset;
    if (mode !== 'schedule') return;
    const $ = (id) => document.getElementById(id);
    const log = $('log'), form = $('form'), input = $('input'), send = $('send');
    const rpc = async (path, params) => {
        const r = await fetch(`/interview/${token}/${path}`, {
            method: 'POST', headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({jsonrpc: '2.0', method: 'call', params}),
        });
        return (await r.json()).result || {error: 'ai'};
    };
    const add = (text, me) => {
        const div = document.createElement('div');
        div.className = 'msg' + (me ? ' me' : '');
        div.textContent = text;
        log.appendChild(div);
        div.scrollIntoView({behavior: 'smooth', block: 'end'});
        return div;
    };
    const busy = (on) => { send.disabled = input.disabled = on; document.querySelectorAll('#slots button').forEach(b => b.disabled = on); };
    const ERR = 'Có lỗi, vui lòng thử lại. / Something went wrong, please try again.';

    // ---------------- scheduling
    if (mode === 'schedule') {
        const slotsBox = $('slots');
        const renderSlots = (slots) => {
            slotsBox.replaceChildren(...slots.map((s, i) => {
                const b = document.createElement('button');
                b.className = 'ghost'; b.textContent = s; b.dataset.index = i; return b;
            }));
        };
        const handle = (res) => {
            if (res.error === 'closed') { add(res.message || 'Đã đóng. / Closed.'); form.hidden = true; return; }
            if (res.error) { add(ERR); return; }
            add(res.reply);
            if (res.slots) renderSlots(res.slots);
            if (res.closed) { form.hidden = true; slotsBox.hidden = true; }
            if (res.booked) setTimeout(() => location.reload(), 1500);
        };
        slotsBox.addEventListener('click', async (e) => {
            const b = e.target.closest('button'); if (!b) return;
            busy(true); try { handle(await rpc('pick', {index: +b.dataset.index})); } catch { add(ERR); } finally { busy(false); }
        });
        form.addEventListener('submit', async (e) => {
            e.preventDefault();
            const text = input.value.trim(); if (!text) return;
            add(text, true); input.value = '';
            busy(true); try { handle(await rpc('schedule', {message: text})); } catch { add(ERR); input.value = text; } finally { busy(false); }
        });
        return;
    }

})();
